import { nearestAspectRatio, type AspectRatio } from './sizes'

// Local, licence-free placeholder tiles (ASSET-INVENTORY 6.2). Generated by scripts/gen-placeholders.mjs as PNG
// (next/image has dangerouslyAllowSVG: false). Same-origin paths always pass the media allow-list, and mock mode uses
// them so `remotePatterns` is never exercised. Never replace these with a remote URL (CI fails on Unsplash/Google).

export const PLACEHOLDER_SRC: Readonly<Record<AspectRatio, string>> = {
  '1:1': '/placeholders/tile-1x1.png',
  '4:3': '/placeholders/tile-4x3.png',
  '3:2': '/placeholders/tile-3x2.png',
  '16:9': '/placeholders/tile-16x9.png',
  '4:5': '/placeholders/tile-4x5.png',
}

/** Intrinsic size of each tile file (width 960). Used as width/height so the fallback never changes the box. */
export const PLACEHOLDER_SIZE: Readonly<Record<AspectRatio, { width: number; height: number }>> = {
  '1:1': { width: 960, height: 960 },
  '4:3': { width: 960, height: 720 },
  '3:2': { width: 960, height: 640 },
  '16:9': { width: 960, height: 540 },
  '4:5': { width: 960, height: 1200 },
}

/**
 * 8x8 PNG gradient in the sand to paper-deep tones, 150 bytes. Palette-tone constant used when a DTO carries no
 * `blurDataUrl` (ARCH-001 13.3), so nothing flashes white. Printed by `node scripts/gen-placeholders.mjs`.
 */
export const DEFAULT_BLUR_DATA_URL =
  'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAgAAAAICAIAAABLbSncAAAAIElEQVR42mN4fu8CVsT0/98/rIjpHw4Z3Dr+4wBUtAMAPiC7r/WeSgcAAAAASUVORK5CYII='

export function placeholderFor(ratio: AspectRatio): string {
  return PLACEHOLDER_SRC[ratio]
}

export function placeholderForSize(width: number, height: number): string {
  return PLACEHOLDER_SRC[nearestAspectRatio(width, height)]
}
